6	/// Enforce the minimal compatibility contract for the Rust OpenAI server.
7	pub(super) fn validate_request_compat(
8	    request: &CompletionRequest,
9	    served_model_names: &[String],
10	) -> Result<(), ApiError> {
11	    // This path is intentionally scoped to the minimum surface needed by
12	    // `vllm-bench` random workload compatibility, so unsupported legacy
13	    // completions features fail early here.
14	    if !served_model_names.iter().any(|n| n == &request.model) {
15	        return Err(ApiError::model_not_found(request.model.clone()));
16	    }
17	
18	    if request.stream_options.is_some() && !request.stream {
19	        bail_invalid_request!(
20	            param = "stream_options",
21	            "stream_options are only supported when stream=true."
22	        );
23	    }
24	
25	    if request.n.unwrap_or(1) > 1 {
26	        bail_invalid_request!(param = "n", "Only n=1 is supported.");
27	    }
28	
29	    if request.max_tokens == Some(0) && !request.echo {
30	        bail_invalid_request!(
31	            param = "max_tokens",
32	            "max_tokens=0 is only supported when echo=true."
33	        );
34	    }
35	
36	    if request.echo && matches!(request.prompt, Prompt::TokenIds(_)) {
37	        bail_invalid_request!(
38	            param = "echo",
39	            "echo is not supported with token-ID prompts."
40	        );
41	    }
42	
43	    if request.suffix.is_some() {
44	        bail_invalid_request!(param = "suffix", "suffix is not supported.");
45	    }
46	
47	    if let Some(logprobs) = request.logprobs
48	        && logprobs > i32::MAX as u32
49	    {
50	        bail_invalid_request!(
51	            param = "logprobs",
52	            "`logprobs` must fit within a signed 32-bit integer."
53	        );
54	    }
55	
56	    if let Some(prompt_logprobs) = request.prompt_logprobs {
57	        if request.stream && (prompt_logprobs > 0 || prompt_logprobs == -1) {
58	            bail_invalid_request!(
59	                param = "prompt_logprobs",
60	                "`prompt_logprobs` are not available when `stream=true`."
61	            );
62	        }
63	
64	        if prompt_logprobs < 0 && prompt_logprobs != -1 {
65	            bail_invalid_request!(
66	                param = "prompt_logprobs",
67	                "`prompt_logprobs` must be a non-negative value or -1."
68	            );
69	        }
70	    }
71	
72	    if request.use_beam_search {
73	        bail_invalid_request!(
74	            param = "use_beam_search",
75	            "use_beam_search is not supported."
76	        );
77	    }
78	
79	    // ---- Reject parameters that are accepted for deserialization but not yet
80	    // implemented ----
81	
82	    if request.length_penalty.is_some() {
83	        bail_invalid_request!(param = "length_penalty", "length_penalty is not supported.");
84	    }
85	    if !request.spaces_between_special_tokens {
86	        bail_invalid_request!(
87	            param = "spaces_between_special_tokens",
88	            "spaces_between_special_tokens is not supported."
89	        );
90	    }
91	    if request.truncate_prompt_tokens.is_some() {
92	        bail_invalid_request!(
93	            param = "truncate_prompt_tokens",
94	            "truncate_prompt_tokens is not supported."
95	        );
96	    }
97	
98	    Ok(())
99	}
