181	        assert!(
182	            validate_request_compat(&request, &served_names(&["Qwen/Qwen1.5-0.5B-Chat"])).is_ok()
183	        );
184	    }
185	
186	    #[test]
187	    fn validate_request_compat_rejects_prompt_only_without_echo() {
188	        let request = CompletionRequest {
189	            stream: false,
190	            echo: false,
191	            max_tokens: Some(0),
192	            ..base_request()
193	        };
194	        assert!(
195	            validate_request_compat(&request, &served_names(&["Qwen/Qwen1.5-0.5B-Chat"])).is_err()
196	        );
197	    }
